import app from 'flarum/forum/app';
import Hero from 'flarum/forum/components/Hero';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import PageStructure from 'flarum/forum/components/PageStructure';
import Icon from 'flarum/common/components/Icon';
import ItemList from 'flarum/common/utils/ItemList';
/**
 * A page hero built like core's own (Hero, Hero-title, Hero-subtitle), so
 * every theme styles it the way it styles the welcome and messages heroes.
 */
export default class DocketHero extends Hero {
  className() {
    return 'DocketHero';
  }
  bodyItems() {
    const items = new ItemList();
    items.add('content', m("div", {
      className: "containerNarrow"
    }, this.contentItems().toArray()), 80);
    return items;
  }
  contentItems() {
    const items = new ItemList();
    items.add('title', m("h1", {
      className: "Hero-title"
    }, m(Icon, {
      name: this.attrs.icon
    }), " ", this.attrs.title), 100);
    if (this.attrs.subtitle) items.add('subtitle', m("div", {
      className: "Hero-subtitle"
    }, this.attrs.subtitle), 90);
    return items;
  }
}

/**
 * Docket's pages laid out as core lays out the discussion list: core's hero,
 * the forum's own sidebar where the index keeps it (the title control on a
 * phone), and the page beside it.
 */
export function docketPage(className, hero, content, loading = false) {
  return m(PageStructure, {
    className: 'DocketPage ' + className,
    loading: loading,
    hero: () => m(DocketHero, hero),
    sidebar: () => m(IndexSidebar, null)
  }, content);
}

/** What the forum's nav is labelled with on a phone when none of its links is this page. */
export function docketNav(label) {
  app.current.set('titleControlLabel', label);
}
flarum.reg.add('ernestdefoe-docket', 'forum/components/DocketHero', DocketHero);